from pathlib import Path
import datetime,hashlib,json
R=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
assert not (R/'config.json').exists()
inputs=json.loads((R/'input_manifest.json').read_text())
for x in inputs:assert x['status']=='CAPTURED_CURRENT_VINTAGE' and sha(R/'raw'/f"{x['series']}.csv")==x['sha256']
parent=R.parent/'sentiment_phase3_20261119'
man=json.loads((parent/'results_v1_1/run_manifest.json').read_text())
panels={str(p.relative_to(R.parent)):sha(p) for p in sorted((parent/'private_v1_1').glob('*_panel.csv'))}
for p,s in panels.items():assert man['raw_and_result_hashes'][str(Path(p).relative_to('sentiment_phase3_20261119'))]==s
c={'run_id':'phase4_20261119_v1','question':'Do equal-versus-modified-cap Nasdaq100 relative participation and real-rate environment add medium-term information beyond price, VIX and funding controls?', 'end':'2026-11-17','input_manifest_sha256':sha(R/'input_manifest.json'),'parent_run_manifest_sha256':sha(parent/'results_v1_1/run_manifest.json'),'parent_panel_hashes':panels,'new_features':{'breadth20':'NDXE paired-session return20 minus NDX paired-session return20','breadth60':'NDXE paired-session return60 minus NDX paired-session return60','real_level':'DFII10 percent','real_change20':'DFII10 minus 20 prior nonmissing source observations','interactions':['breadth60 * real_change20','risk_appetite/100 * real_change20']},'alignment':'Second most recent nonmissing source observation strictly before local date; maximum 7 calendar days age; NDXE/NDX paired same source date; resets at asymmetric missing dates','parent_outcomes':'Use exactly parent 4/8/12-calendar-week next-close outcomes and segment/period exclusions','symbols':['US.QQQ','US..SOX','SH.000001','SH.000688'],'China_interpretation':'US external structure/rate environment only, NOT China breadth','states':{'narrowing':'source NDX return60>0 AND breadth60<0','broadening':'source NDX return60>0 AND breadth60>=0','weak':'source NDX return60<=0'},'models':{'base':['return20','return60','ma60_gap','drawdown252','volatility20','risk_appetite','vix_change20','credit_level','credit_change20','rate_change20'],'variants':['base','base_breadth','base_real','base_joint'],'add_breadth':['breadth20','breadth60'],'add_real':['real_level','real_change20'],'add_joint':['breadth20','breadth60','real_level','real_change20','breadth_real','risk_real'],'alpha':[1.,10.],'primary_alpha':1.,'train':'expanding, only labels ended before test January1; same complete rows for all variants','minimum_train':756,'test_years':list(range(2011,2027)),'standardize':'train-only population mean and sd, intercept unpenalized','metric':'paired MSE delta versus base, negative favors new variables','secondary':['MAE','sign_accuracy']},'uncertainty':{'replicates':999,'seed':20261119,'blocks':[126,63,252],'primary_block':126,'confidence':.95,'primary_family':'12 symbol by added-model alpha1/h8/all tests, Holm; US main and China external reported separately but family pooled','state_family':'4 narrowing-minus-broadening h8 mean-return contrasts, Holm','interpretation':'exploratory current vintage, correlated markets, one model family, previous history already seen'},'periods':['development','check','late_check','monitor'],'excluded_claims':['pure psychological sentiment','complete market breadth','PIT-certified strategy','news surprise efficacy','causal prediction','universal turning standard']}
(R/'config.json').write_text(json.dumps(c,ensure_ascii=False,indent=2))
(R/'freeze_receipt.json').write_text(json.dumps({'frozen_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'config_sha256':sha(R/'config.json'),'financial_phase4_results_before_freeze':False,'source_inputs_inspected':'metadata, dates, missingness only; no new outcome contrast or fit'},indent=2))
print(json.dumps({'config_sha256':sha(R/'config.json'),'parent_panels':len(panels)}))
